/**
 *  The ONLY error shape the UI ever receives.
 * 
 *  Contains no raw error text, no SQL, no file path and no stack trace — only
 *  a code, a plain-language message and a suggested action (NFR-033,
 *  R-UI-008). Serialises with camelCase keys (`code`, `message`,
 *  `suggestedAction`) and crosses to TypeScript via `specta` (R-ARCH-004).
 */
export type UserFacingError = {
	/**  Machine code; also the i18n key the UI resolves with `t()`. */
	code: ErrorCode,
	/**  Plain-language, patient-data-free message (safe default / fallback). */
	message: string,
	/**  One concrete next step, e.g. `"Try again"` / `"Check the details"`. */
	suggestedAction: string,
};

/**  Result of `verify_backup` (BAK-004). */
export type VerifyBackupResponse = {
	/**  Whether both the checksum and the decrypt-test passed. */
	ok: boolean,
	/**  The body bytes matched the recorded checksum. */
	checksumOk: boolean,
	/**  The first chunk decrypted under the given password. */
	decryptOk: boolean,
};

/**  A visit timeline entry (PAT-005). R3+; EMPTY list for R2. */
export type VisitSummary = {
	/**  Visit id. */
	visitId: string,
	/**  RFC3339 visit instant. */
	visitAt: string,
	/**  Visit kind label. */
	kind: string,
	/**  Headline remedy label, or `None`. */
	headlineRemedyLabel: string | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

